        parse_amount("12.5") == 1250
        parse_amount("-$1,234.56") == -123456
    """
    s = text.strip()
    if not s:
        raise ValueError(f"Empty amount string")

    sign = 1
    if s[0] in ('+', '-'):
        if s[0] == '-':
            sign = -1
        s = s[1:]

    if s.startswith('$'):
        s = s[1:]

    if not s:
        raise ValueError(f"No digits in amount: {text!r}")

    # Split on '.' for fractional part
    if '.' in s:
