        if len(parts) != 2:
            raise ValueError(f"Multiple dots in amount: {text!r}")
        int_part, frac_part = parts
        if len(frac_part) > 2:
            raise ValueError(f"Fractional part has more than 2 digits: {text!r}")
        if not frac_part:
            raise ValueError(f"Empty fractional part: {text!r}")
    else:
        int_part = s
        frac_part = ''

    # Remove commas from integer part
    int_part_clean = int_part.replace(',', '')
    if not int_part_clean.isdigit():
        raise ValueError(f"Invalid integer part in amount: {text!r}")

    # Validate commas placement: commas should separate groups of 3 digits
    if ',' in int_part:
        # Check that commas are in valid positions
        segments = int_part.split(',')
        # First segment can be 1-3 digits, subsequent must be exactly 3
        if len(segments[0]) < 1 or len(segments[0]) > 3:
            raise ValueError(f"Invalid comma placement: {text!r}")
        for seg in segments[1:]:
            if len(seg) != 3:
                raise ValueError(f"Invalid comma placement: {text!r}")

    int_val = int(int_part_clean)
    if frac_part:
        # Pad fractional part to 2 digits
        frac_padded = frac_part.ljust(2, '0')
        frac_val = int(frac_padded)
    else:
